    uint256 constant IC1y = 2382454749574689101220120303082215470013158451245489481875467746651649536102;

    uint256 constant IC2x = 20926734531244703068204303459669058608234214660577238782124505893010077149385;
    uint256 constant IC2y = 12300294966247142135163464257755206321873876200694574614417391554262883622847;

    uint256 constant IC3x = 19851353316477660697514063614441950614086555306037127226001918435993753794396;
