import "./governance/LinealQorum.sol";
/**
 * @title LinealSecureStorage
 * @dev A simple contract that use LinealQorum to store and retrieve a number securely.
 */

contract LinealSecureStorage is LinealQorum {
    uint256 private number;
    constructor(
        address[] memory _machines,
        uint256 _requiredMachines,
        address[] memory _institutions,
        uint256 _requiredInstitutions,
        address[] memory _humans,
        uint256 _requiredHumans,
        uint256 _recoveryQuorum
    )          LinealQorum(
    _machines,
    _requiredMachines,
    _institutions,
    _requiredInstitutions,
    _humans,
    _requiredHumans,
    _recoveryQuorum
    ) {}

    /**
     * @dev Store value in variable
     * @param num value to store
     */
    function store(uint256 num) public onlyServers {
        bytes32 txHash = _computeActionHash("store", abi.encode(num));
        if (!confirmServers(txHash, "store")) return;
        number = num;
    }

    /**
     * @dev Return value
     * @return value of 'number'
     */
    function retrieve() public onlyServers returns (uint256){
        bytes32 txHash = _computeActionHash("retrieve", "");
        if (!confirmServers(txHash, "retrieve")) return 0;
        return number;
    }
}

